('chapter-64','chapter','Sports, disabilities, and aging','I AM - An Olympic Athlete',9,'https://openoregon.pressbooks.pub/greentea/chapter/i-am-an-olympic-athlete/','[{"type":"paragraph","text":"Watch Michael Hubbs talk about his life, training, and challenges. Answer the questions below in your notebook. (Remember, you can listen at 75% speed in Settings on YouTube.)"},{"type":"paragraph","text":"https://www.youtube.com/watch?reload=9&amp;v=4CHgymBHQcg"},{"type":"paragraph","text":"Exercises"},{"type":"paragraph","text":"Here’s a model to follow:"},{"type":"paragraph","text":"Examples"},{"type":"paragraph","text":"I AM"},{"type":"paragraph","text":"(by Nanci Leiton)"},{"type":"paragraph","text":"I AM a mother who raises children to solve problems."},{"type":"paragraph","text":"I AM a person who helps others whenever possible."},{"type":"paragraph","text":"I AM a person who strives to make a kinder world for everyone."},{"type":"paragraph","text":"I AM a teacher who creates a place for people to learn and achieve their goals."},{"type":"paragraph","text":"I AM a gardener who loves to grow green things and eat healthy food."},{"type":"paragraph","text":"I AM a citizen with the best interests of ALL people in my community."}]'::jsonb,117),
('chapter-101','chapter','Sports, disabilities, and aging','Watch and Discuss: The Never-Ending Marathon of Mr. Dharam Singh',10,'https://openoregon.pressbooks.pub/greentea/chapter/watch-and-discuss-the-never-ending-marathon-of-mr-dharam-singh/','[{"type":"heading","level":2,"text":"Directions:"},{"type":"paragraph","text":"Watch this short movie about Mr. Singh. It is 20 minutes long, so plan your time. You will also hear a variety of world Englishes. Some audio is subtitled."},{"type":"paragraph","text":"As you watch the movie, take active listening notes on a separate piece of paper with the title and date at the top of the page."},{"type":"heading","level":2,"text":"Key Vocabulary:"}]'::jsonb,58),
('chapter-258','chapter','Sports, disabilities, and aging','Read it out: Paralympic Games',11,'https://openoregon.pressbooks.pub/greentea/chapter/read-it-out-paralympic-games/','[{"type":"paragraph","text":"Read it out: Paralympic Games"},{"type":"paragraph","text":"Before you read:"},{"type":"paragraph","text":"After you practice, record your slow, clear pronunciation and share your recording."},{"type":"paragraph","text":"Image by Flickr user Stuart Grout"},{"type":"heading","level":2,"text":"Start:"},{"type":"paragraph","text":"Hi, my name is________."},{"type":"heading","level":2,"text":"The Paralympic Games"},{"type":"paragraph","text":"The Paralympic Games are a major international sports event. People with physical disabilities compete in these games. They have included people with amputations, blindness, disabilities that affect movement, and more."},{"type":"paragraph","text":"The Paralympics started as a small gathering of British World War 2 veterans in 1948. They planned new games every four years. They have continued to grow since then. The winter games opened in 1976. The Paralympics became one of the largest international sport events by the early 21st century."},{"type":"paragraph","text":"Paralympians have many different kinds of disabilities, so there are several categories that they compete in. The disabilities are in six general categories. Athletes are placed into groups which vary from sport to sport."},{"type":"paragraph","text":"These athletes work for equal treatment with able-bodied Olympic games participants, who receive much more money. Some Paralympians have also overcome even more challenges, and participated in the Olympic Games."},{"type":"paragraph","text":"Thank you!"},{"type":"heading","level":2,"text":"Finish"},{"type":"paragraph","text":"Adapted from Wikipedia"},{"type":"paragraph","text":"Paralympic Games. (2020, March 30). Wikipedia, The Free Encyclopedia . Retrieved 18:39, July 30, 2020 from https://simple.wikipedia.org/w/index.php?title=Paralympic_Games&oldid=6883229 ."},{"type":"paragraph","text":"You can use this button to record your voice. Listen before you share it, to make sure everything recorded clearly."}]'::jsonb,222),
('chapter-260','chapter','Sports, disabilities, and aging','Group Activity: A New Olympic Sport',12,'https://openoregon.pressbooks.pub/greentea/chapter/group-activity-a-new-olympic-sport/','[{"type":"paragraph","text":"Great news! You have been hired (for free!) by the International Olympic Committee to help choose a new sport to add to the Olympic Games."},{"type":"paragraph","text":"Instructions:"},{"type":"heading","level":2,"text":"The 4 key questions"},{"type":"paragraph","text":"For each question, you can discuss more questions:"},{"type":"heading","level":2,"text":"Three examples"},{"type":"paragraph","text":"Discuss these sports with the 4 key questions. They are sports that have been suggested in the past:"},{"type":"heading","level":2,"text":"Brainstorm"},{"type":"heading","level":2,"text":"Share"},{"type":"paragraph","text":"Be ready to share with the rest of the class."}]'::jsonb,70),
