values ('Portland People and Places', 'Timothy Krause', 'https://openoregon.pressbooks.pub/portlandpeopleandplaces/', 'CC BY', 'https://creativecommons.org/licenses/by/4.0/', 'pressbooks', '{"base_url":"https://openoregon.pressbooks.pub","book_slug":"portlandpeopleandplaces"}'::jsonb, 'ready')
