select s.id, v.ext, v.kind, v.part, v.title, v.pos, v.url, v.blocks, now(), v.wc, 'parsed'
from s, (values
('front-matter-104','front-matter',null,'Welcome!',0,'https://openoregon.pressbooks.pub/portlandpeopleandplaces/front-matter/welcome/','[{"type":"paragraph","text":"Portland is a wonderful place. It has many interesting stories. Please enjoy them!"},{"type":"paragraph","text":"Welcome to Portland! We’re glad you are here!"},{"type":"paragraph","text":"— Tim Krause, Instructor English for Speakers of Other Languages Portland Community College December 2018"},{"type":"paragraph","text":"The text was written by Timothy Krause, ESOL Instructor, Portland Community College."},{"type":"paragraph","text":"Images from \"A Strange Hobby\" and \"A Surprise Question\" are used with permission. All rights reserved."},{"type":"paragraph","text":"Other images are in the public domain except where otherwise noted in the alt text."},{"type":"paragraph","text":"This book was funded in part by a grant from Open Oregon Educational Resources ."},{"type":"paragraph","text":"You may also be interested in these titles:"}]'::jsonb,102),
('chapter-94','chapter','Main Body','A Small City',1,'https://openoregon.pressbooks.pub/portlandpeopleandplaces/chapter/a-small-city/','[{"type":"paragraph","text":"This is Susan. She is a student at Portland Community College. She lives in Portland."},{"type":"paragraph","text":"Portland is a small city in Oregon. Oregon is a state in the United States of America."},{"type":"paragraph","text":"There are many trees, rivers, and mountains in Oregon."},{"type":"paragraph","text":"This is the flag of Oregon. It is blue. Oregon is called the \"Beaver State.\""},{"type":"paragraph","text":"Summers are warm and dry in Portland. Susan likes the sun."},{"type":"paragraph","text":"Winters in Portland are different. They are cool and wet. Susan doesn''t like the rain."},{"type":"paragraph","text":"Portland is near a mountain. The name of the mountain is Mt. Hood."},{"type":"paragraph","text":"(Mt. = Mount. This is another word for \"mountain.\")"},{"type":"paragraph","text":"This is the flag of Portland. The green is nature. The blue lines are two rivers. The names of the rivers are the Willamette River and the Columbia River."},{"type":"paragraph","text":"Portland has many bridges. Some are for cars. Some are for trains. Some are for people and bikes."},{"type":"paragraph","text":"Portland has five parts. Susan lives in Southeast."},{"type":"paragraph","text":"Susan has a garden with lots of trees and flowers. One flower is a pink rose."},{"type":"paragraph","text":"Portland has lots of parks. Many parks have gardens with roses. Portland is the “City of Roses.”"},{"type":"paragraph","text":"Susan rides her bike to the parks. Portland has many bike lanes on the streets. It''s easy to ride a bike in Portland."},{"type":"paragraph","text":"Susan eats lunch outside in the summer. She likes food carts. There are many food carts in Portland. Susan is vegan."},{"type":"paragraph","text":"(vegan = she does not eat animals)"},{"type":"paragraph","text":"Susan also likes soccer. Portland has two soccer teams. They are called the Portland Thorns (women) and the Portland Timbers (men)."},{"type":"paragraph","text":"Susan likes living in Portland."}]'::jsonb,269),
('chapter-84','chapter','Main Body','A Strange Hobby',2,'https://openoregon.pressbooks.pub/portlandpeopleandplaces/chapter/a-strange-hobby/','[{"type":"paragraph","text":"That is Brian. He is always learning new things. He learns very fast."},{"type":"paragraph","text":"Brian has a strange hobby. He plays the bagpipes. The bagpipes make weird music."},{"type":"paragraph","text":"(\"Weird\" means unusual.)"},{"type":"paragraph","text":"One day, Brian sees something strange in the trash. He thinks it is a bicycle. It isn''t. But it''s a unicycle!"},{"type":"paragraph","text":"The unicycle isn''t easy to ride. It has only one wheel. There are no handlebars. There are no brakes. But Brian likes to learn new things. He learns very fast. He rides well."},{"type":"paragraph","text":"A friend asks Brian, \"Can you play the bagpipes and ride the unicycle at the same time?\" \"Yes, I think I can,\" says Brian."},{"type":"paragraph","text":"And he does. Brian rides his unicycle and plays the bagpipes. He also thinks of an unusual name: the Unipiper."},{"type":"paragraph","text":"Brian tries to be on TV. They say no. Brian tries again. They say no again."},{"type":"paragraph","text":"Then Brian wears a mask like Darth Vader. He plays music from the movie \"Star Wars.\" He makes a YouTube video , and 2,000,000 people watch it!"},{"type":"paragraph","text":"(Darth Vader is a person in the \"Star Wars\" movies.)"},{"type":"paragraph","text":"Now everybody knows the Unipiper. He is in newspapers, and he is on TV. People come to Portland to see the Unipiper."},{"type":"paragraph","text":"Look and listen carefully! Maybe one day you will see and hear the Unipiper, too!"},{"type":"paragraph","text":"Do you want to know more about the Unipiper? Then visit his web page at www.unipiper.com ."},{"type":"paragraph","text":"Comprehension Questions"},{"type":"paragraph","text":"Discussion Question"},{"type":"paragraph","text":"Talk with a classmate. What are your hobbies? Say what you like to do. Example: I read books. I play soccer. I bake cakes."}]'::jsonb,263),
('chapter-75','chapter','Main Body','A Flip of the Coin',3,'https://openoregon.pressbooks.pub/portlandpeopleandplaces/chapter/a-flip-of-the-coin/','[{"type":"paragraph","text":"The year is 1845. There is a new city in Oregon. It is by the Willamette River."},{"type":"paragraph","text":"People come from far away. They want to live there. They move to Oregon in wagons."},{"type":"paragraph","text":"“What is the new city''s name?” the people ask."},{"type":"paragraph","text":"Francis Pettygrove comes from Portland, Maine. He wants to name the new city Portland."},{"type":"paragraph","text":"Asa Lovejoy comes from Boston, Massachusetts. He wants to name the new city Boston."},{"type":"paragraph","text":"The men can’t decide. So they find a penny. They flip the coin three times."},{"type":"paragraph","text":"First, it is heads. “Portland!” says Francis."},{"type":"paragraph","text":"Second, it is tails. “Boston!” says Asa."},{"type":"paragraph","text":"Third, it is heads again. “Portland!” says Francis. “Portland” says Asa."},{"type":"paragraph","text":"The name of the new city is Portland, Oregon."},{"type":"paragraph","text":"The city looks very different today …"},{"type":"paragraph","text":"… but the penny is the same. You can see the penny at a museum in downtown Portland. It is at the Oregon Historical Society."}]'::jsonb,151),
('chapter-402','chapter','Main Body','A Surprise Question',4,'https://openoregon.pressbooks.pub/portlandpeopleandplaces/chapter/a-surprise-question/','[{"type":"paragraph","text":"Isaac loves Amy. He wants to marry her."},{"type":"paragraph","text":"Isaac uses his cell phone. He sends Amy a text. The text says “Come to my parents’ house.” Amy goes to their house."},{"type":"paragraph","text":"Amy sees Isaac''s brother. He tells her to sit in Isaac’s car. She laughs."},{"type":"paragraph","text":"He gives her headphones. She wears them, but she feels confused."},{"type":"paragraph","text":"The car moves. Amy hears music in the headphones. Isaac’s brother is making noise. She laughs again."},{"type":"paragraph","text":"Amy sees her friends. She is surprised. They are singing and dancing in the street!"},{"type":"paragraph","text":"Amy sees Isaac''s family, too."},{"type":"paragraph","text":"Then Amy sees her family on laptop computers."},{"type":"paragraph","text":"Everyone is singing and dancing in the street."},{"type":"paragraph","text":"Amy is smiling. She is happy. She loves music, friends and family. But why are they doing this?"},{"type":"paragraph","text":"Then she sees Isaac. The music stops. What is happening?"},{"type":"paragraph","text":"Everyone is very quiet. Then Isaac asks Amy to marry him. Amy says “Yes.”"},{"type":"paragraph","text":"Everyone is happy. Isaac and Amy are getting married."},{"type":"paragraph","text":"Comprehension Questions"},{"type":"paragraph","text":"Discussion Question"},{"type":"paragraph","text":"Talk to a classmate. What happens in the story? Use your own words. Then watch the video below. Talk about family."}]'::jsonb,185),
('chapter-69','chapter','Main Body','An Immigrant''s Story',5,'https://openoregon.pressbooks.pub/portlandpeopleandplaces/chapter/an-immigrants-story/','[{"type":"paragraph","text":"Simon Benson is 17 years old. He leaves Norway, and he comes to the United States. Simon is an immigrant."},{"type":"paragraph","text":"Simon lives in Wisconsin. He works at a store. He also studies English. He wants to make more money."},{"type":"paragraph","text":"Now Simon is 28 years old. He moves to Oregon. He buys a big forest."},{"type":"paragraph","text":"Simon starts a business. It cuts trees for wood. Business is good."},{"type":"paragraph","text":"Simon is very rich. He has a lot of money. He has a nice house in downtown Portland."},{"type":"paragraph","text":"Many people work for Simon. Work in the forest is not easy. The workers are thirsty."},{"type":"paragraph","text":"Sometimes the workers drink beer at lunch."},{"type":"paragraph","text":"Simon doesn''t like beer. He says, “Drink water, not beer.”"},{"type":"paragraph","text":"Simon watches a parade on the Fourth of July. He sees a little girl. She is crying. She is thirsty, but she has no water."},{"type":"paragraph","text":"Simon gives $10,000 to Portland. The city makes 20 drinking fountains. They are called “Benson Bubblers.”"},{"type":"paragraph","text":"Today there are more than 70 “Benson Bubblers” in downtown Portland. Have you seen one?"},{"type":"paragraph","text":"Comprehension Questions"},{"type":"paragraph","text":"Discussion Question"},{"type":"paragraph","text":"Talk with a classmate. Are you an immigrant? Where are you from? What is your story?"}]'::jsonb,193),
('chapter-127','chapter','Main Body','A Tiny Park',6,'https://openoregon.pressbooks.pub/portlandpeopleandplaces/chapter/a-tiny-park/','[{"type":"paragraph","text":"The year is 1948. Dick works at a newspaper in Portland. He writes stories about the city."},{"type":"paragraph","text":"He looks out his window every day. He sees a busy street. He wishes for a park."},{"type":"paragraph","text":"One day he sees a small circle in the street. \"What is that?\" Dick asks his friend."},{"type":"paragraph","text":"\"It is a hole. It is for a new street light,\" says Dick’s friend."},{"type":"paragraph","text":"Dick is a writer. He likes to tell stories. Dick thinks of a better story about the hole in the street."},{"type":"paragraph","text":"Dick looks at the hole again. Then his eyes grow big. He sees a little man in the hole! The little man is a leprechaun!"},{"type":"paragraph","text":"(A leprechaun is a small Irish fairy.)"},{"type":"paragraph","text":"Dick runs to the hole. He catches the lucky leprechaun."},{"type":"paragraph","text":"The leprechaun gives Dick one wish. Dick wishes for a park."},{"type":"paragraph","text":"The leprechaun points to the hole in the street. “Here is your park!” says the little man."},{"type":"paragraph","text":"Dick pulls weeds. He plants flowers. He thinks it is the best park. “It’s a big park for little leprechauns,” Dick says. He calls it Mill Ends Park."},{"type":"paragraph","text":"Dick writes many newspaper stories about the park. He says leprechauns live there. Many people read the stories in the newspaper. They all love the little park."},{"type":"paragraph","text":"Mill Ends Park is the smallest park in the world.You can visit it today. It is in downtown Portland at Southwest Taylor Street."},{"type":"paragraph","text":"Comprehension Questions"},{"type":"paragraph","text":"Discussion Question"},{"type":"paragraph","text":"Dick makes a wish in the story. He wants a park. What do you wish for?"},{"type":"paragraph","text":"Examples:"}]'::jsonb,255),
('chapter-243','chapter','Main Body','A Man with an Umbrella',7,'https://openoregon.pressbooks.pub/portlandpeopleandplaces/chapter/a-man-with-an-umbrella/','[{"type":"paragraph","text":"It rains a lot in Portland. It usually rains 44 inches every year."},{"type":"paragraph","text":"Some people use an umbrella."},{"type":"paragraph","text":"Others do not."},{"type":"paragraph","text":"One man in downtown Portland always uses an umbrella. He is the \"umbrella man\"!"},{"type":"paragraph","text":"The umbrella man is a sculpture in Pioneer Courthouse Square. The name of the sculpture is \"Allow Me.\" But everybody calls it the \"umbrella man.\""},{"type":"paragraph","text":"John Seward Johnson is the artist. He made the sculpture in 1983. It is bronze. It weighs 460 pounds. It is 6 feet, 10 inches tall."},{"type":"paragraph","text":"John Seward Johnson is a famous artist. His sculptures are all over the world. This one is in Sarasota, Florida. It is called \"Embracing Peace.\""},{"type":"paragraph","text":"Sometimes people think \"the umbrella man\" is a real man. He looks friendly! Many people take photographs with him."},{"type":"paragraph","text":"Sometimes people even dress him up!"},{"type":"paragraph","text":"Some people say umbrellas are only for tourists. But when it rains 44 inches a year, everybody needs an umbrella — even statues!"},{"type":"paragraph","text":"Comprehension Questions"},{"type":"paragraph","text":"Discussion Question"},{"type":"paragraph","text":"Talk to a classmate: Visit the artist''s website at Seward Johnson Atelier . Look at more of his sculptures. Which one do you like? Why?"}]'::jsonb,188),
('chapter-248','chapter','Main Body','A Big Flood',8,'https://openoregon.pressbooks.pub/portlandpeopleandplaces/chapter/a-big-flood/','[{"type":"paragraph","text":"There is a new city on the Columbia River. The city is between Vancouver and Portland. The name is Vanport."},{"type":"paragraph","text":"Companies nearby make ships for the Second World War. The companies need more workers. The workers need houses."},{"type":"paragraph","text":"So the companies build a new city for the workers in 1942. About 42,000 people live in Vanport during the war."},{"type":"paragraph","text":"It is the state''s second largest city. About 40% of the people are African-American. Vanport gives jobs to the first black teachers and police in the state."},{"type":"paragraph","text":"Vanport has stores, a hospital, a movie theater, and schools. There is a college to help soldiers returning from the war. Later, the college becomes Portland State University."},{"type":"paragraph","text":"In 1948, there is much snow in the winter."},{"type":"paragraph","text":"There is more rain in the spring."},{"type":"paragraph","text":"The snow and rain send a lot of water into the Columbia River. The river becomes very high. They say the city is safe."},{"type":"paragraph","text":"However, the city was built quickly. They used cheap materials."},{"type":"paragraph","text":"Only a dirt wall separates the city from the river. On May 30, 1948, the dirt wall breaks."},{"type":"paragraph","text":"Water from the river flows into the city."},{"type":"paragraph","text":"The city is under water in less than two hours."},{"type":"paragraph","text":"15 people die. Buildings are damaged or destroyed. 17,500 people have no homes now."},{"type":"paragraph","text":"The city of Vanport is not built again. The land becomes part of Portland. Today, it is a racetrack and a golf course."},{"type":"paragraph","text":"The city is gone. Only stories remain."},{"type":"paragraph","text":"Comprehension Questions"},{"type":"paragraph","text":"Discussion Question"},{"type":"paragraph","text":"Talk with a classmate. A flood is a natural disaster. What are other kinds of natural disasters? For example: earthquake, typhoon, hurricane, tornado, wildfire, drought. What happens in your country?"}]'::jsonb,278),
('chapter-253','chapter','Main Body','A City of Bridges',9,'https://openoregon.pressbooks.pub/portlandpeopleandplaces/chapter/a-city-of-bridges/','[{"type":"paragraph","text":"Portland has many nicknames. Two nicknames are \"Bridge City\" and \"Bridgetown\". That is because 12 bridges cross the Willamette River in Portland."},{"type":"paragraph","text":"The St. Johns Bridge connects North Portland and Northwest Portland. It is a suspension bridge. It is the tallest bridge in Portland."},{"type":"paragraph","text":"The next bridge is the Burlington Northern Railroad Bridge. Only trains use this bridge. About 30-35 trains cross the bridge every day."},{"type":"paragraph","text":"The Fremont Bridge is part of Interstate 405. It is the longest bridge in Oregon. It has two levels. Each level is called a deck. Cars on the upper deck go west; cars on the lower deck go east."},{"type":"paragraph","text":"The Broadway Bridge is very old. It was built in 1913. Cars and trucks use this bridge. The Portland Streetcar uses this bridge, too. It connects the Lloyd District with downtown Portland."},{"type":"paragraph","text":"The Steel Bridge opened in 1912. It has two decks. Both decks can move up and down for boats underneath. The lower deck is for bicycles, people, and long trains. The upper deck is for cars and short MAX trains."},{"type":"paragraph","text":"The Burnside Bridge opened in 1926. It is made of concrete. That means it is very heavy. It opens for boats about 35 times a month. There is a skateboard park under the east side, and the Portland Saturday Market is under the west side."},{"type":"paragraph","text":"The next bridge is the Morrison Bridge. It is a very busy bridge. It was built in 1958, but there were other bridges here before this one. There are special lights at night with different colors and patterns."},{"type":"paragraph","text":"The Hawthorne Bridge is the oldest highway bridge in Portland. It was built in 1910. Every day 8,000 people ride bicycles across this bridge. 800 buses use this bridge, too, with 17,400 people."},{"type":"paragraph","text":"The Marquam Bridge is part of Interstate 5. It is the busiest bridge in the state. More than 140,000 vehicles cross the bridge every day. It has two decks. Many people do not like this bridge. They think it is not very pretty."},{"type":"paragraph","text":"Tilikum Crossing opened in 2015. \"Tilikum\" comes from the Native American word for \"people\". So it is sometimes called the \"Bridge of the People.\" That''s because no cars or trucks can use this bridge. It is for people who walk or ride a bike. The busses, the Portland Streetcar, and the MAX Orange Line also use this bridge."},{"type":"paragraph","text":"The Ross Island Bridge opened in 1926. It is also Highway 26. The name \"Ross Island Bridge\" comes from an island in the river. This bridge does not open for boats."},{"type":"paragraph","text":"Sellwood Bridge is the last bridge in Portland. It was built in 1925, but the government replaced that bridge in 2016. Engineers made the bridge safer in an earthquake."},{"type":"paragraph","text":"Comprehension Questions"},{"type":"paragraph","text":"Discussion Questions"},{"type":"paragraph","text":"Talk to your classmate. Portland has many nicknames:"},{"type":"paragraph","text":"Why do people use these nicknames?"},{"type":"paragraph","text":"Do you have a nickname? What is it? Why do people call you by that name?"}]'::jsonb,488)
