values ('Home and School', 'Timothy Krause', 'https://openoregon.pressbooks.pub/homeandschool/', 'CC BY', 'https://creativecommons.org/licenses/by/4.0/', 'pressbooks', '{"base_url":"https://openoregon.pressbooks.pub","book_slug":"homeandschool"}'::jsonb, 'ready')
