from s, (values
('front-matter-4','front-matter',null,'Welcome!',0,'https://openoregon.pressbooks.pub/homeandschool/front-matter/welcome/','[{"type":"paragraph","text":"Primary Navigation"},{"type":"paragraph","text":"Book Contents Navigation"},{"type":"paragraph","text":"Welcome!"},{"type":"paragraph","text":"Niki and Matt are classmates"},{"type":"paragraph","text":"Minako and Tom study in the computer lab"},{"type":"paragraph","text":"Wu buys food"},{"type":"paragraph","text":"Omar goes to the doctor"},{"type":"paragraph","text":"Sunee and Chet live in an apartment"},{"type":"paragraph","text":"Bob gets ready for school"},{"type":"paragraph","text":"Ann visits the market"},{"type":"paragraph","text":"Hugo goes to school and work"},{"type":"paragraph","text":"Malee asks about the weather"},{"type":"paragraph","text":"We celebrate different holidays"},{"type":"paragraph","text":"Welcome! This book has stories about life at home and at school. Enjoy!"},{"type":"paragraph","text":"— Tim Krause, Instructor English for Speakers of Other Languages Portland Community College October 2018"},{"type":"paragraph","text":"This book was funded in part by a grant from Open Oregon Educational Resources ."},{"type":"paragraph","text":"Images are public domain or used included under Creative Commons licensing."},{"type":"paragraph","text":"The text was written by Timothy Krause, ESOL Instructor, Portland Community College."},{"type":"paragraph","text":"You may also be interested in these titles:"}]'::jsonb,132),
('chapter-5','chapter','Main Body','Niki and Matt are classmates',1,'https://openoregon.pressbooks.pub/homeandschool/chapter/niki-and-matt-are-classmates/','[{"type":"paragraph","text":"Her name is Niki."},{"type":"paragraph","text":"His name is Matt."},{"type":"paragraph","text":"They are happy."},{"type":"paragraph","text":"They are friends."},{"type":"paragraph","text":"They go to English class."},{"type":"paragraph","text":"They are talking. \"Hi! How are you?\""},{"type":"paragraph","text":"\"I''m good. Thanks. How are you?\""},{"type":"paragraph","text":"Comprehension Questions"},{"type":"paragraph","text":"Discussion Question"},{"type":"paragraph","text":"Introduce yourself: What is your first name? What is your last name? Where are you from?"},{"type":"paragraph","text":"Sources"},{"type":"paragraph","text":"Images courtesy of stockimages at FreeDigitalImages.net."}]'::jsonb,59),
('chapter-20','chapter','Main Body','Minako and Tom study in the computer lab',2,'https://openoregon.pressbooks.pub/homeandschool/chapter/minako-and-tom-study-in-the-computer-lab/','[{"type":"paragraph","text":"Her name is Minako."},{"type":"paragraph","text":"Her classroom is big."},{"type":"paragraph","text":"She studies English on a computer."},{"type":"paragraph","text":"This is a monitor. She reads on a monitor."},{"type":"paragraph","text":"This is a keyboard. She types on a keyboard."},{"type":"paragraph","text":"This is a mouse. She clicks with a mouse."},{"type":"paragraph","text":"Minako listens to the computer."},{"type":"paragraph","text":"A classmate says \"Shh!\""},{"type":"paragraph","text":"Minako uses headphones."},{"type":"paragraph","text":"Tom asks, \"Where is a printer?\""},{"type":"paragraph","text":"\"It''s over there.\""},{"type":"paragraph","text":"Tom sees the printer."},{"type":"paragraph","text":"\"Thanks!\""},{"type":"paragraph","text":"Comprehension Questions"},{"type":"paragraph","text":"Discussion Question"},{"type":"paragraph","text":"What things are in your classroom? Point to them."},{"type":"paragraph","text":"Sources"},{"type":"paragraph","text":"Images of Minako courtesy of mrsiraphol at freedigitalphotos.net"},{"type":"paragraph","text":"Images of Tom courtesy of artur84 at freedigitalphotos.net"},{"type":"paragraph","text":"All other images are public domain."}]'::jsonb,103),
('chapter-22','chapter','Main Body','Wu buys food',3,'https://openoregon.pressbooks.pub/homeandschool/chapter/wu-buys-food/','[{"type":"paragraph","text":"Wu buys food."},{"type":"paragraph","text":"He buys lemons."},{"type":"paragraph","text":"Wu buys garlic."},{"type":"paragraph","text":"He buys rice."},{"type":"paragraph","text":"He buys fish."},{"type":"paragraph","text":"He buys apples."},{"type":"paragraph","text":"He buys cabbage."},{"type":"paragraph","text":"Wu goes home. He cooks dinner."}]'::jsonb,27),
('chapter-24','chapter','Main Body','Omar goes to the doctor',4,'https://openoregon.pressbooks.pub/homeandschool/chapter/omar-goes-to-the-doctor/','[{"type":"paragraph","text":"His name is Omar."},{"type":"paragraph","text":"Her name is Rosa."},{"type":"paragraph","text":"They are married."},{"type":"paragraph","text":"They are parents. He is a father. She is a mother. They have two children. They have two daughters."},{"type":"paragraph","text":"They don''t have a son."},{"type":"paragraph","text":"Omar is sick today."},{"type":"paragraph","text":"They visit the doctor''s office."},{"type":"paragraph","text":"They talk to a nurse."},{"type":"paragraph","text":"\"How many children do you have?\""},{"type":"paragraph","text":"\"We have two daughters.\""},{"type":"paragraph","text":"\"How old are your daughters?\""},{"type":"paragraph","text":"Rosa answers, \"One is 3 years old. One is 4 years old.\""},{"type":"paragraph","text":"Here is the doctor."},{"type":"paragraph","text":"\"Omar is OK.\""},{"type":"paragraph","text":"Comprehension Questions"},{"type":"paragraph","text":"Discussion Question"},{"type":"paragraph","text":"How do you feel today?"},{"type":"paragraph","text":"Sources"},{"type":"paragraph","text":"Family images courtesy of David Castillo Dominici at freedigitalphotos.net"},{"type":"paragraph","text":"Medical images courtesy of stockimages at freedigitalphotos.net"},{"type":"paragraph","text":"All other images are public domain."}]'::jsonb,115),
('chapter-26','chapter','Main Body','Sunee and Chet live in an apartment',5,'https://openoregon.pressbooks.pub/homeandschool/chapter/sunee-and-chet-live-in-an-apartment/','[{"type":"paragraph","text":"Her name is Sunee."},{"type":"paragraph","text":"His name is Chet."},{"type":"paragraph","text":"They are married."},{"type":"paragraph","text":"They are husband and wife."},{"type":"paragraph","text":"They live in Portland."},{"type":"paragraph","text":"They live in an apartment."},{"type":"paragraph","text":"Chet is in the kitchen. He cooks dinner."},{"type":"paragraph","text":"Sunee is in the living room. She studies English."},{"type":"paragraph","text":"They have a son. He plays a game."},{"type":"paragraph","text":"They have a daughter. She does homework."},{"type":"paragraph","text":"The children are in the living room."},{"type":"paragraph","text":"\"Dinner is ready. Let''s eat!\""},{"type":"paragraph","text":"They watch TV after dinner."},{"type":"paragraph","text":"Comprehension Questions"},{"type":"paragraph","text":"Discussion Question"},{"type":"paragraph","text":"What do you do after dinner?"},{"type":"paragraph","text":"Sources"},{"type":"paragraph","text":"Images of Sunee and Chet Vichaya Kiatying-Angsulee at FreeDigitalPhotos.net"},{"type":"paragraph","text":"Image of son by kdshutterman at FreeDigitalPhotos.net"},{"type":"paragraph","text":"Image of daughter by khunaspix at FreeDigitalPhotos.net"},{"type":"paragraph","text":"All other images are public domain."}]'::jsonb,114),
('chapter-28','chapter','Main Body','Bob gets ready for school',6,'https://openoregon.pressbooks.pub/homeandschool/chapter/bob-gets-ready-for-school/','[{"type":"paragraph","text":"His name is Bob."},{"type":"paragraph","text":"Bob needs things for school. He has a list."},{"type":"paragraph","text":"Bob needs five things."},{"type":"paragraph","text":"He asks his mother. \"Do you have a pencil?\""},{"type":"paragraph","text":"\"No, I don''t have a pencil.\""},{"type":"paragraph","text":"She has rubber bands."},{"type":"paragraph","text":"\"Thanks!\""},{"type":"paragraph","text":"Bob asks his father. \"Do you have a pencil?\""},{"type":"paragraph","text":"\"No, I don''t have a pencil.\""},{"type":"paragraph","text":"His father has an eraser."},{"type":"paragraph","text":"\"Thanks!\""},{"type":"paragraph","text":"He asks his sisters. \"Do you have a pencil?\""},{"type":"paragraph","text":"\"No, we don''t have a pencil.\""},{"type":"paragraph","text":"They have a pen."},{"type":"paragraph","text":"\"Thanks!\""},{"type":"paragraph","text":"Bob asks his brother. \"Do you have a pencil?\""},{"type":"paragraph","text":"\"No, I don''t have a pencil.\""},{"type":"paragraph","text":"His brother has a paperclip."},{"type":"paragraph","text":"\"Thanks!\""},{"type":"paragraph","text":"Bob needs five things. He has four things."},{"type":"paragraph","text":"Bob doesn''t have a pencil."},{"type":"paragraph","text":"Who has a pencil?"},{"type":"paragraph","text":"\"Thank you, Max!\""},{"type":"paragraph","text":"\"Woof!\""},{"type":"paragraph","text":"Comprehension Questions"},{"type":"paragraph","text":"Discussion Question"},{"type":"paragraph","text":"Find these things in your classroom:"},{"type":"paragraph","text":"Sources"},{"type":"paragraph","text":"Images of Bob and his sisters by artur84 at FreeDigitalPhotos.net"},{"type":"paragraph","text":"Image of the paperclip by lobster20 at FreeDigitalPhotos.net"},{"type":"paragraph","text":"Image of the brother and the rubber bands by David Castillo Dominici at FreeDigitalPhotos.net"},{"type":"paragraph","text":"Images of the mother and father by stockimages at FreeDigitalPhotos.net"},{"type":"paragraph","text":"All other images are public domain."}]'::jsonb,179),
('chapter-30','chapter','Main Body','Ann visits the market',7,'https://openoregon.pressbooks.pub/homeandschool/chapter/ann-visits-the-market/','[{"type":"paragraph","text":"Her name is Ann."},{"type":"paragraph","text":"Ann buys food at a market."},{"type":"paragraph","text":"The market has many fruits and vegetables."},{"type":"paragraph","text":"There are red tomatoes."},{"type":"paragraph","text":"There are brown mushrooms."},{"type":"paragraph","text":"There is a watermelon."},{"type":"paragraph","text":"Ann has a list."},{"type":"paragraph","text":"\"Do you have red apples?\""},{"type":"paragraph","text":"\"No. We don''t have apples. We have pears.\""},{"type":"paragraph","text":"\"I have red apples.\" Ann buys red apples."},{"type":"paragraph","text":"Ann sees green peppers, red peppers, and yellow peppers. She buys a green pepper."},{"type":"paragraph","text":"She sees red grapes."},{"type":"paragraph","text":"She sees cabbage."},{"type":"paragraph","text":"She sees garlic."},{"type":"paragraph","text":"Ann buys yellow corn …"},{"type":"paragraph","text":"… and one orange for a snack."},{"type":"paragraph","text":"Ann reads her list. \"Do I have everything?\""},{"type":"paragraph","text":"Ann sees one more thing … … flowers!"},{"type":"paragraph","text":"She has fruits, vegetables, and flowers."},{"type":"paragraph","text":"\"Now it''s time to make something to eat!\""},{"type":"paragraph","text":"Comprehension Questions"},{"type":"paragraph","text":"Discussion Question"},{"type":"paragraph","text":"Where do you buy food? What do you buy?"},{"type":"paragraph","text":"Sources"},{"type":"paragraph","text":"Images of Ann by Witthaya Phonsawat at FreeDigitalPhotos.net"},{"type":"paragraph","text":"Image of man with pear by marin at FreeDigitalPhotos.net"},{"type":"paragraph","text":"Image of man with apple by imagerymajestic at FreeDigitalPhotos.net"},{"type":"paragraph","text":"All other images are public domain."}]'::jsonb,166),
('chapter-246','chapter','Main Body','Hugo goes to school and work',8,'https://openoregon.pressbooks.pub/homeandschool/chapter/hugo-goes-to-school-and-work/','[{"type":"paragraph","text":"He is Hugo. His dog is Luis."},{"type":"paragraph","text":"Hugo is a student. He has English class on Monday, Wednesday, and Friday."},{"type":"paragraph","text":"He takes a bus to school."},{"type":"paragraph","text":"Sometimes he rides his bike."},{"type":"paragraph","text":"He has many friends in English class."},{"type":"paragraph","text":"He studies in the computer lab."},{"type":"paragraph","text":"Hugo has a job. He works on Tuesday, Thursday, and Saturday. He takes the train to work."},{"type":"paragraph","text":"He drives a truck."},{"type":"paragraph","text":"Sometimes he drives a van."},{"type":"paragraph","text":"Every day, Hugo walks outside. He walks with his dog. They go to a park."},{"type":"paragraph","text":"They do not like the rain."},{"type":"paragraph","text":"Luis does not like water."},{"type":"paragraph","text":"\"Is it raining today?\""},{"type":"paragraph","text":"Comprehension Questions"},{"type":"paragraph","text":"Discussion Question"},{"type":"paragraph","text":"How do you come to school? Do you drive? Do you take the bus?"},{"type":"paragraph","text":"Sources"},{"type":"paragraph","text":"\"Man and Dog - Beach at Niteroi - Rio de Janeiro - Brazil\" by Adam Jones, Ph.D. is licensed under CC BY-SA 3.0"},{"type":"paragraph","text":"\"Fort Worth Library Computer Lab\" by Informationwave is licensed under CC BY 3.0"},{"type":"paragraph","text":"\"TriMet D40LFR bus\" by Steve Morgan is licensed under CC BY-SA 3.0"},{"type":"paragraph","text":"\"Man on Bike; Night\" by Sascha Kohlmann is licensed under CC BY-SA 2.0"},{"type":"paragraph","text":"\"Men and women at a town hall meeting\" by CDC/ Dawn Arlotta acquired from Public Health Image Library is in the Public Domain"},{"type":"paragraph","text":"\"Man in computer lab\" is in the Public Domain, CC0"},{"type":"paragraph","text":"\"Trimet Train\" is in the Public Domain"},{"type":"paragraph","text":"\"StrongPak Navistar Utilimaster delivery truck\" by MobiusDaXter is licensed under CC BY-SA 3.0"},{"type":"paragraph","text":"\"Dodge RAM ProMaster parcel delivery van\" by MobiusDaXter is licensed under CC BY-SA 4.0"},{"type":"paragraph","text":"\"Man Walking Dog\" is copyright Neil Theasby and licensed for reuse under this Creative Commons Licence ."},{"type":"paragraph","text":"\"Downpour in Chinatown. Toronto, Canada.\" by Unknown is licensed under CC BY 2.0"},{"type":"paragraph","text":"\"Wet dog - Tygrys\" by Wiktor Batorski is licensed under CC BY-SA 3.0"},{"type":"paragraph","text":"\"Doggie in the Window\" by Linnaea Mallette is in the Public Domain, CC0"}]'::jsonb,303),
('chapter-34','chapter','Main Body','Malee asks about the weather',9,'https://openoregon.pressbooks.pub/homeandschool/chapter/malee-asks-about-the-weather/','[{"type":"paragraph","text":"She is Malee."},{"type":"paragraph","text":"She lives in Portland. The weather is beautiful today."},{"type":"paragraph","text":"She calls her parents. They live in California. \"How is the weather today?\""},{"type":"paragraph","text":"\"It''s nice. It''s warm and sunny.\""},{"type":"paragraph","text":"Malee''s aunt lives in Thailand. She calls her aunt. \"How is the weather today?\""},{"type":"paragraph","text":"\"It is very hot today.\""},{"type":"paragraph","text":"Her friend is Ahmed. He lives in Seattle. Malee texts Ahmed."},{"type":"paragraph","text":"Her friend Laura is in Toronto."},{"type":"paragraph","text":"\"Hi, Laura. How is the weather in Toronto?\""},{"type":"paragraph","text":"\"It''s cold and snowy. I have my hat, my scarf, and my gloves.\""},{"type":"paragraph","text":"Malee calls her friend Lou. He lives in England. \"How is the weather today?\""},{"type":"paragraph","text":"\"It''s cold and rainy. I need my umbrella.\""},{"type":"paragraph","text":"Malee calls her friend Tom. \"How is the weather in Spain?\""},{"type":"paragraph","text":"\"It is nice. I can eat lunch outside.\""},{"type":"paragraph","text":"Malee''s friend Susan is at the beach. \"How is the weather?\""},{"type":"paragraph","text":"\"It is windy and foggy. I can''t see the ocean.\""},{"type":"paragraph","text":"Malee calls her husband. His name is Joe."},{"type":"paragraph","text":"Joe doesn''t answer his phone."},{"type":"paragraph","text":"Comprehension Questions"},{"type":"paragraph","text":"Discussion Question"},{"type":"paragraph","text":"How is the weather today? How was the weather yesterday?"},{"type":"paragraph","text":"Go to weather.com . How is the weather in your country?"},{"type":"paragraph","text":"Sources"},{"type":"paragraph","text":"All images of \"Malee\" by tiniroma at FreeDigitalPhotos.net."},{"type":"paragraph","text":"\"Pioneer Courthouse Square\" by Steve Morgan is licensed under CC BY-SA 3.0"},{"type":"paragraph","text":"Image of \"parents\" by Witthaya Phonsawat at FreeDigitalPhotos.net."},{"type":"paragraph","text":"\"Red Hot\" by Matthew Kenwrick is licensed under CC BY-ND 2.0"},{"type":"paragraph","text":"Image of \"Ahmed\" by nenetus at FreeDigitalPhotos.net."},{"type":"paragraph","text":"Image of text message is public domain."},{"type":"paragraph","text":"Images of \"Laura\" by adamr at FreeDigitalPhotos.net."},{"type":"paragraph","text":"\" Alpha shivering on the deck - Pub Bistro, Thredbo\" by Alpha is licensed under CC BY-SA 2.0"},{"type":"paragraph","text":"Image of \"Tom\" by stockimages at FreeDigitalPhotos.net."},{"type":"paragraph","text":"Image of \"Susan\" is public domain."},{"type":"paragraph","text":"Image of \"Tom\" by Tuomas_Lehtinen at FreeDigitalPhotos.net."}]'::jsonb,287),
('chapter-32','chapter','Main Body','We celebrate different holidays',10,'https://openoregon.pressbooks.pub/homeandschool/chapter/we-celebrate-different-holidays/','[{"type":"paragraph","text":"We have many holidays in the United States."},{"type":"paragraph","text":"We celebrate holidays in different ways."},{"type":"paragraph","text":"New Year''s Day is January 1. We have parties on December 31. We call it New Year''s Eve."},{"type":"paragraph","text":"Martin Luther King, Jr. Day is in January. Martin Luther King, Jr., worked for peace and equal rights for everyone. We remember him on the third Monday of January."},{"type":"paragraph","text":"(Jr. = junior)"},{"type":"paragraph","text":"Valentine''s Day is February 14. Some people give candy, flowers, and cards to the person they love. (February 14 is also Oregon''s birthday!)"},{"type":"paragraph","text":"Mother''s Day is in May. We remember our mothers in many ways."},{"type":"paragraph","text":"Memorial Day is also in May. Memorial Day is the last Monday in May. We remember people who died in war."},{"type":"paragraph","text":"Father''s Day is in June. We remember our fathers in many ways."},{"type":"paragraph","text":"Independence Day is July 4. Our country''s birthday is July 4, 1776. We often have flags, fireworks, picnics, and parades."},{"type":"paragraph","text":"Labor Day is in September. Labor Day is the first Monday in September. We remember all workers."},{"type":"paragraph","text":"Halloween is October 31. Children wear fun costumes, and they get candy."},{"type":"paragraph","text":"Veterans Day is November 11. We remember all soldiers."},{"type":"paragraph","text":"Thanksgiving Day is in November. Families often spend time together and eat a big meal."},{"type":"paragraph","text":"Christmas is December 25. There are many holidays in December, such as Hanakkuh, Kwanzaa, and the winter solstice. We like to spend time with our friends and family."},{"type":"paragraph","text":"Comprehension Questions"},{"type":"paragraph","text":"Discussion Question"},{"type":"paragraph","text":"Tell your classmates about a holiday in your country."},{"type":"paragraph","text":"Sources"},{"type":"paragraph","text":"All images are public domain."}]'::jsonb,252)
) as v(ext,kind,part,title,pos,url,blocks,wc)
on conflict (source_id, external_id) do update set parsed_blocks=excluded.parsed_blocks, word_count=excluded.word_count, parsed_at=now(), status='parsed';